    "name": "Allanamiento La denunciante manifestó que su hermano Cristián Alfredo Córdoba hace nueve meses se encuentra viviendo en la ciudad de Helvecia ya que por el consumo de droga perdió a su familia en la ciudad de Esperanza, estando ahora al cuidado de su madre. Que el llamado Cristián Córdoba se encuentra bajo tratamiento psiquiátrico por consumo de cocaína, pero que en horas de la madrugada o cuando queda solo los llamados “Gamuza” Cortes, Diego Leguiza alias “Chanchero” y Brian Baumgartner alias “Caraca” le llevan droga a domicilio. Agregando además que un día su hermano le indicó que compraba droga en una vivienda ubicada en Barrio Santa Teresita de la ciudad de Helvecia, por calle Buenos Aires, de la despensa de “Pichu” dos casas más hacia el cardinal oeste, teniendo la casa una construcción tipo de madera. Se le recibió entrevista a la denunciante quien aportó el número de teléfono del llamado Brian Baumgartner.",
