    "name": "Allanamiento DESCRIPCIÓN / RELATO\nRELATO:en la fecha siendo las 11:50hs personal de Cdo Rco. Procedió a la aprehensión de la llamada ACOSTA AILEN ALEJANDRA HIJA ACOSTA MIGUEL Y NUÑEZ ALEJANDRA, ARGENTINA, CASADA DE 26 AÑOS DE EDAD, INSTRUIDO, DESOCUPADA, DNI N° 41.790.934, FN 17.03.1999 EN ROSARIO, DOMICILIADA EN DR. F. RIVAS. 264 DE ROSARIO, desde la Unidad Penitenciaria 1 quienes solicitaron colaboración ya que una femenina intentaba ingresar a la visita, con una identidad falsa, cómo también ingresando un objeto oculto en el interior de su cuerpo, lo cual se observó por el escáner, negándose a ser requisada, alterando el orden y el normal desarrollo de la visita. Ante lo cual una vez en la U1 la femenina hizo entrega de un bulto de color negro compacto que extrajo por su voluntad de sus partes íntimas, agregando en forma espontánea que sería droga, por lo cual se le dio conocimiento e intervención a personal de PDI a fines de llevar a cabo las pruebas de campo. Siendo las 14.40 hs consulta y orden con el dr Persello fiscal, por parte de personal de PDI, Ordeno: que en cuanto al material secuestrado (celular, balanza, sellos, tijera, cocaína y marihuana) quede a cargo de PDI, en tanto que la involucrada sea entregada a esta dependencia fines de ser notificada de la causa y se evacue nueva consulta con la planilla prontuarial. Una vez en esta dependencia luego de obtener los antecedentes de Acosta se labro nueva consulta con fiscal en turno Dr. Persello, quien siendo las 20:00hs ordenó la detención de la femenina por causa RESISTENCIA A LA AUTORIDAD e INFRACCIÓN ART 139 PÁRRAFO 3RO CP.DE LA LEY 23.737. Haciendo constar que será remitida a la Comisaria 3º de Barrancas por carecer esta dependencia de alojamiento transitorio.",
