    "name": "Allanamiento Se dispone a labrar la presente a los fines de dejar debidamente documentadas las siguientes circunstancias: en la fecha la Comisario Mariela Ramos, Jefe de PDI, Distrito San Jorge, en horas de la tarde toma conocimiento por parte de la Sra. Alejandra Carrizo; Coordinadora General de la Policía de Investigaciones, que en la ciudad de El Trébol; más precisamente en el domicilio sito en calle Juan de Garay Nro. 712 había una plantación con características similares a cannabis. Al mismo tiempo Carrizo envía una foto donde se observa a través de un tapial plantas con características antes descriptas. Conforme a lo expuesto, esta instancia y con el objeto de corroborar lo expresado, nos comisionamos en móvil N° 1240 focus no identificable a la ciudad de El Trébol. Estando in situ y dando inicio a las pesquisas se establece el lugar y la vivienda conforme al domicilio de Juan de Garay Nro. 712, resultando que el mismo se encuentra en zona urbanizada de la ciudad de mención. Se recabaron datos de vecinos del lugar, para lograr individualizar la vivienda y posibles moradores donde se pudo saber que en el domicilio en cuestión viviría la llamada PAMELA LUQUE DNI 36.477.956 junto a dos menores que serían sus hijos. La misma se encuentra distanciada de su pareja que se llamaría ANDRES HERNANDEZ (únicos datos) quien actualmente no viviría en el lugar. La vivienda en cuestión seria propiedad del llamado HECTOR SEGATTI DNI 6.295.376; una persona mayor con dificultades físicas y de salud que estaría al cuidado de LUQUE quien sería nieta de este. Posteriormente y contando con la gentileza de una vecina que tiene una casa adyacente a la vivienda sindicada y que es colindante con la vivienda en cuestión, pudiendo visualizar abundantes plantas que sobrepasan el tapial y que serían compatibles con cannabis. Por tal motivo y contando con dicha información se solicita pasar a la Fase operativa con motivo de dar fin a este delito de tenencia y/o comercialización de material estupefaciente (marihuana), a la espera de su respuesta. Se prosiguen con las diligencias de rigor.",
