    "lng": -61.714896,
    "name": "Allanamiento Que en fecha 31 del corriente mes y año, se recibe informe de parte del Jefe de Comisaria Cuarta El Trébol, quien da cuenta que: “Quien suscribe Comisario ROLDAN, ADRIAN GUSTAVO, Jefe de Comisaria Cuarta de la ciudad de El Trébol – U.R. XVIII; Por intermedio de la presente cumplo en informar a usted, a los fines legales que correspondan, que se comunica telefónicamente a la línea de emergencias 101 de esta Comisaria Cuarta U.R. XVIII, de una femenina la cual se identificó como DANISA BELEN RAMOS, s/c en calle Colon N° 1156 de este medio, quien manifestó que en el Domicilio de Avda. Independencia y Calle Sargento Cabral de este medio, en la intersección sureste, donde habita el ciudadanos RAUL GERMAN ALBARRACIN, hay plantas de marihuana; que este señor se mueve en una motocicleta marca Honda Wave y que además frecuenta mucho en el lugar una camioneta de color blanco y un automóvil tipo Ford fiesta, no estando segura de marca, el cual es de color rojo. Dejando un teléfono de contacto para ampliar en caso de ser necesario (03401-15416702) Que es todo cuanto puedo informar,”\nAsí las cosas esta Unidad Operativa dan inicio a la investigación y prosecución de la misma. Quedando a su disposición, a la espera de lo que se ordene para su prosecución.",
