    "name": "Allanamiento (...)en circunstancias que al transitar por calle Tomas Lubary a la altura catastral 3800 en su sentido de circulación oeste- este entre las calles Mosconi al Este y su similar calle Artigas al Oeste, se advierte que desde un kiosco/almacén el cual se encuentra con revoque y en su frente dos ventanas de color blanco con rejas de color negra, una puerta de chapa de color negra como así también un portón de chapa de color negro tipo garaje, ubicado sobre la vereda sur de Tomas Lubary, aproximadamente 25 metros hacia el cardinal Este de la intersección con calle Artigas, donde se puede observar un masculino retirarse del lugar, el cual manipula un objeto de pequeñas dimensiones similar a un envoltorio, comúnmente utilizado para resguardar material estupefaciente; es por ello, que ante la presunción de encontrarnos ante un presunto punto de comercialización de sustancias ilícitas, se estableció un puesto de observación y vigilancia con vista directa al lugar mencionado, unos 30 minutos aproximadamente donde se puede apreciar varias personas acercarse al comercio, las cuales realizan compras de mercaderías, como así también se puede captar la llegada de un masculino el cual viste ropas remera de color celeste y blanca, short negro con vivos amarillos y naranja y gorro tipo piluso de color gris y mochila de color negra con detalles en color lila, quien manipula dinero en sus manos para luego entregarlo a quien despacha, espera unos segundos recibiendo desde el interior de la vivienda, por la ventana donde se realizan las ventas un envoltorio de pequeñas dimensiones, retirándose de forma apresurada, observando hacia los lados, llevando el objeto en su mano derecha como es evidenciado en las imágenes que se adjuntan a continuación, es dable de mención que para esta instancia policial estaríamos frente a un punto de venta de material estupefaciente, el cual es disimulado por el comercio que funciona en el lugar.",
